type I18nValue = { language: UiLanguage; setLanguage: (language: UiLanguage) => void; t: (key: string, values?: Record<string, string | number>) => string; formatDate: (value: string) => string };
const I18nContext = createContext<I18nValue>({ language: "en", setLanguage: () => {}, t: (key) => messages.en[key] ?? key, formatDate: (value) => value });

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<UiLanguage>(() => {
    try { return localStorage.getItem(STORAGE_KEY) === "ja" ? "ja" : "en"; } catch { return "en"; }
  });
  const setLanguage = (next: UiLanguage) => {
    setLanguageState(next);
    try { localStorage.setItem(STORAGE_KEY, next); } catch { /* Storage may be unavailable. */ }
  };
  const value = useMemo<I18nValue>(() => ({
    language,
    setLanguage,
    t: (key, values = {}) => {
      const source = messages[language][key] ?? messages.en[key] ?? key;
      return source.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(values[name] ?? `{{${name}}}`));
    },
    formatDate: (value) => {
      const parsed = new Date(value.includes("T") ? value : value.replace(" ", "T"));
      return Number.isNaN(parsed.getTime()) ? value : new Intl.DateTimeFormat(language === "en" ? "en-US" : "ja-JP", { dateStyle: "medium", timeStyle: "short" }).format(parsed);
    },
  }), [language]);
  useEffect(() => {
    try { localStorage.setItem(STORAGE_KEY, language); } catch { /* Storage may be unavailable. */ }
  }, [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() { return useContext(I18nContext); }
